# Each row: name, category, solvents, what is extracted/removed, end uses, regulatory notes, status, sources
CO2REG = "CO2 baseline: EU Part I (GMP) · US GRAS 21 CFR 184.1240 (processing aid) · ANZ GMP processing aid · CN GB 2760 Table C.1 (no residue limit) · JP designated additive. See section 2."
CO2S = ["EU","CFR_CO2"]
def spice(name, latin, what, uses, cat="Spice oleoresin / extract", extra_src=None, extra_reg=""):
    return dict(name=name, latin=latin, cat=cat, solv="Supercritical CO2", what=what, uses=uses,
                reg=("Canada: CO2 listed for 'Spice extracts; Natural extractives; (naming the flavour) flavour' at GMP. " + extra_reg + CO2REG),
                status="Commercial", src=["FLAVEX"]+(extra_src or [])+["HC"]+CO2S)
def herb(name, latin, what, uses, extra_src=None):
    return spice(name, latin, what, uses, cat="Herb extract / flavoring", extra_src=extra_src)
def oil(name, latin, what, uses, src=None, status="Commercial"):
    return dict(name=name, latin=latin, cat="Specialty oil / lipid", solv="Supercritical CO2", what=what, uses=uses,
                reg=CO2REG,
                status=status, src=(src or ["FLAVEX"])+["HC"]+CO2S)
def flav(name, latin, what, uses, src=None):
    return dict(name=name, latin=latin, cat="Flavoring extract", solv="Supercritical CO2", what=what, uses=uses,
                reg="Canada: CO2 listed for '(naming the flavour) flavour; Natural extractives' at GMP. " + CO2REG,
                status="Commercial", src=(src or ["FLAVEX"])+["HC"]+CO2S)

